 private static String displayName(String key){return key.contains(":")?key.substring(key.indexOf(':')+1):key;}
 private static boolean playerKey(String key){return key.matches("[A-Za-z0-9_]{1,16}");}
 private String publicOwner(PrivateChat.Entry entry){if(entry.channelKind().equals("private")||entry.channelKind().equals("official"))return null;return entry.channelKind().startsWith("favorite-")||favoriteNames.contains(entry.senderId().toLowerCase(Locale.ROOT))?entry.senderId():null;}
 /** Starred messages are shown with the official layout; their source is the separate ★信息 store. */
 private List<PrivateChat.Entry> source(){if(!(official&&savedView))return PrivateChatStore.entries();savedRows.clear();String account=LedgerStore.account();var out=new ArrayList<PrivateChat.Entry>();for(var row:SavedChatStore.entries()){var entry=new PrivateChat.Entry(account,"★信息",false,row.time(),row.text(),"saved",row.source(),row.sender().isEmpty()?"聊天框":row.sender(),"");savedRows.put(entry,row);out.add(entry);}return out;}
 private boolean inView(PrivateChat.Entry e){return e.channelKind().equals(savedView?"saved":"official");}
 private boolean matchesSelected(PrivateChat.Entry entry){if(official)return inView(entry);if(playerKey(selected))return effectivePublic()?selected.equalsIgnoreCase(publicOwner(entry)):entry.channelKind().equals("private")&&entry.peer().equalsIgnoreCase(selected);return entry.peer().equalsIgnoreCase(selected);}
 private boolean effectivePublic(){return publicView&&playerKey(selected)&&favoriteNames.contains(selected.toLowerCase(Locale.ROOT));}
 private void readCurrent(){if(playerKey(selected)&&!channels.isEmpty()&&(effectivePublic()?channels.stream().allMatch("private"::equals):!channels.contains("private")))return;PrivateChatStore.read(effectivePublic()?"收藏:"+selected:selected);}
 private void switchPublic(boolean value){publicView=value;offset=historyPage=0;recordQuery="";listMotion.reset();arrivals.clear();readCurrent();rebuildWidgets();}
 private static String sourceLabel(PrivateChat.Entry e){String label=switch(ChatChannels.kind(e)){case "trade"->"交易";case "private"->"私聊";case "land"->"领地 · "+e.scope();case "nation"->"国家 · "+e.scope();default->"全球";};return label+switch(e.originKind()){case "nether"->" · 地狱远征";case "dungeon"->" · 地牢裂隙";case "end"->" · 末地";default->"";};}

 private boolean pendingRecordSearch;
 private void liveSearch(boolean records){pendingRecordSearch=records;searchRefreshQueued=true;}
 private void applyLiveSearch(){searchRefreshQueued=false;boolean records=pendingRecordSearch;var previous=records?recordSearch:search;int cursor=previous.getCursorPosition();if(!records){if(official)recordQuery=query;peerOffset=0;}offset=historyPage=0;listMotion.reset();arrivals.clear();rebuildWidgets();var field=records?recordSearch:search;setFocused(field);field.setFocused(true);field.setCursorPosition(Math.min(cursor,field.getValue().length()));}

 private void search(){searchSerial++;searchRefreshQueued=false;listMotion.reset();arrivals.clear();if(official){recordQuery=query;selected=savedView?"★信息":"官方";historyPage=offset=0;rebuildWidgets();return;}boolean valid;try{PrivateChat.command(query,"check");valid=true;}catch(IllegalArgumentException bad){valid=false;}boolean found=PrivateChatStore.entries().stream().anyMatch(e->e.text().toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)));if(valid&&!found){wantFocus=true;if(!selected.equalsIgnoreCase(query))draft="";selected=query;remember();historyPage=0;offset=0;}if(found){selected="";recordQuery=query;}peerOffset=0;rebuildWidgets();}
 private void send(){send(false);}
 private void send(boolean verified){String person=selected.startsWith("收藏:")?selected.substring(3):selected;if(person.matches("[A-Za-z0-9_]{1,16}")&&!LocalRoster.online(person)){status="玩家当前不在线。";return;}if(selected.isEmpty()||draft.isBlank()||draft.contains("\n")||draft.contains("\r")||minecraft.getConnection()==null||minecraft.getCurrentServer()==null||!ServerAccess.isSimmc(minecraft.getCurrentServer().ip)){status="请进入 SIMMC 并选择玩家。";return;}String command;try{command=PrivateChat.command(person,draft);}catch(IllegalArgumentException bad){status="请选择有效会话。";return;}if(command.length()>256){status="消息过长，请缩短后重试。";return;}if(!verified&&(selected.startsWith("领地:")||selected.startsWith("国家:"))){String peer=selected,body=draft;var connection=minecraft.getConnection();status="正在检查成员资格…";ChatChannelIcons.checkMembership(peer,allowed->{if(minecraft.screen!=this||minecraft.getConnection()!=connection||!selected.equals(peer)||!draft.equals(body))return;if(allowed)send(true);else status="请检查是否为成员、领地/国家是否已改名，然后重试。";});return;}if(!ClientCommandQueue.chat(command)){status="发送太快，每秒最多 3 条，请稍后重试。";return;}if(effectivePublic()){publicView=false;recordQuery="";offset=historyPage=0;}draft="";status="";wantFocus=true;rebuildWidgets();}
