 private void layoutSidebar(ArchiveLayout l){sidebarWidgets.clear();int end=62;for(var child:children())if(child instanceof net.minecraft.client.gui.components.AbstractWidget widget&&(widget instanceof Action||widget instanceof ChatSearchButton||widget instanceof ChatChannelButton||widget instanceof EditBox)&&widget.getX()>=l.left()&&widget.getX()<l.left()+l.sidebar()&&widget.getY()>=62&&!Set.of("一键已读","导入日志").contains(widget.getMessage().getString())){sidebarWidgets.put(widget,widget.getY());end=Math.max(end,widget.getY()+(widget instanceof EditBox?13:widget.getHeight()));}maxSidebarScroll=Math.max(0,end-(height-80));sidebarScroll=Math.min(sidebarScroll,maxSidebarScroll);sidebarWidgets.forEach((widget,y)->{widget.setY(y-sidebarScroll);int top=widget.getY()-(widget instanceof EditBox?3:0),bottom=widget.getY()+(widget instanceof EditBox?13:widget.getHeight());widget.visible=top>=62&&bottom<=height-80;});}
