 private void closeModal(){modalPrompt=null;modalAction=null;modalName=null;modalButtons.clear();rebuildWidgets();}
 private void confirmModal(){String name=modalRename?modalName.getValue().strip():"";if(modalRename&&(modalPlayerRename?!name.matches("[A-Za-z0-9_]{1,16}"):!PrivateChat.scopeValid(name)))return;var action=modalAction;closeModal();action.accept(name);rebuildWidgets();}
 private double arrivalOffset(PrivateChat.Entry entry,long now){Long start=arrivals.get(entry);if(start==null)return 0;double t=Math.max(0,(now-start)/1e9);if(t>1){arrivals.remove(entry);return 0;}return 12*(1+15*t)*Math.exp(-15*t);}
