 private int separatorHeight(int index){return index>=0&&index<timeBreaks.size()&&!timeBreaks.get(index).isEmpty()?12:0;}
 private int rowHeight(int index){return 16+blocks.get(index).size()*10+separatorHeight(index);}
 private int hdrWidth(String label){return Math.max(30,font.width(label)+10);}
 /** The record dialog's search: sets the text and shows the first page of the matches. */
 void applyRecordQuery(String text){recordQuery=text;offset=0;historyPage=0;rebuildWidgets();}
 /** The record dialog's jump: jumps to the time or date it was given. */
 void applyJump(String text){jumpValue=text;jumpToTime();}
 private void jumpToTime(){try{long target=ChatDates.jump(jumpValue,LedgerStore.BEIJING);long from=fromDate.isBlank()?Long.MIN_VALUE:ChatDates.parse(fromDate,LocalDate.now(LedgerStore.BEIJING)).atStartOfDay(LedgerStore.BEIJING).toInstant().toEpochMilli(),to=toDate.isBlank()?Long.MAX_VALUE:ChatDates.parse(toDate,LocalDate.now(LedgerStore.BEIJING)).plusDays(1).atStartOfDay(LedgerStore.BEIJING).toInstant().toEpochMilli();var jumpEntries=source().stream().filter(e->matchesSelected(e)&&(official?inView(e):!e.channelKind().equals("official")&&ChatChannels.accepts(channels,e))&&e.time()>=from&&e.time()<to).toList();var all=savedView&&official?jumpEntries.stream().map(e->new PrivateChat.Run(e,e.time(),1)).toList():official?PrivateChat.officialRuns(jumpEntries):PrivateChat.runs(jumpEntries);int index=0;while(index<all.size()-1&&all.get(index).end()<target)index++;historyPage=Math.max(0,(all.size()-1-index)/500);offset=0;rebuildWidgets();int local=-1;for(int i=0;i<runs.size();i++)if(runs.get(i).end()>=target){local=i;break;}if(local>=0){int before=0;for(int i=0;i<local;i++)before+=rowHeight(i);offset=Math.max(0,totalPixels-(height-135)-before);}status="";}catch(RuntimeException bad){status="请输入例如 2026-10-01、21:00 或 2026-10-01 21:00:00。";}}
 private void complete(){if(composer==null)return;if(draft.equals(completed)&&!suggestions.isEmpty()){suggestionIndex=(suggestionIndex+1)%suggestions.size();composer.setValue(suggestions.get(suggestionIndex));completed=draft;return;}int cursor=Math.min(composer.getCursorPosition(),draft.length()),start=cursor;while(start>0&&!Character.isWhitespace(draft.charAt(start-1)))start--;String fragment=draft.substring(start,cursor),before=draft.substring(0,start),after=draft.substring(cursor);suggestions=LocalRoster.players(minecraft).stream().map(LocalRoster.Player::name).filter(name->name.toLowerCase(Locale.ROOT).startsWith(fragment.toLowerCase(Locale.ROOT))).distinct().sorted(String.CASE_INSENSITIVE_ORDER).limit(80).map(name->before+name+after).toList();if(!suggestions.isEmpty()){suggestionIndex=0;composer.setValue(suggestions.getFirst());completed=draft;}}

